extends Node

signal action_rebound(action: StringName, event: InputEvent)

const DEFAULT_PATH = "user://input_map.cfg"
var _default_events: Dictionary = {}

func _ready() -> void:
	# Capture defaults at startup
	var actions = [
		"move_up", "move_down", "move_left", "move_right", "interact", "jump"
	]
	for action in actions:
		_default_events[action] = get_action_event(action)

func rebind_action(action: StringName, new_event: InputEvent) -> void:
	for ev in InputMap.action_get_events(action):
		if ev is InputEventKey or ev is InputEventJoypadButton:
			InputMap.action_erase_event(action, ev)
	InputMap.action_add_event(action, new_event)
	action_rebound.emit(action, new_event)

func get_action_event(action: StringName) -> InputEvent:
	var events = InputMap.action_get_events(action)
	if events.size() > 0:
		return events[0]
	return null

func save_to_file(path: String = DEFAULT_PATH) -> void:
	var config = ConfigFile.new()
	var actions = [
		"move_up", "move_down", "move_left", "move_right", "interact", "jump"
	]
	for action in actions:
		var ev = get_action_event(action)
		if ev is InputEventKey:
			config.set_value("bindings", action, {"type": "key", "keycode": ev.keycode})
		elif ev is InputEventJoypadButton:
			config.set_value("bindings", action, {"type": "joypad", "button": ev.button_index})
	config.save(path)

func load_from_file(path: String = DEFAULT_PATH) -> bool:
	var config = ConfigFile.new()
	var err = config.load(path)
	if err != OK:
		return false
	if config.has_section("bindings"):
		for action in config.get_section_keys("bindings"):
			var data = config.get_value("bindings", action)
			var event: InputEvent
			if typeof(data) == TYPE_DICTIONARY:
				if data.get("type") == "key":
					event = InputEventKey.new()
					event.keycode = data.get("keycode", 0)
					# Set physical_keycode to keep it consistent if needed, but keycode is enough for now
				elif data.get("type") == "joypad":
					event = InputEventJoypadButton.new()
					event.button_index = data.get("button", 0)
				if event:
					rebind_action(action, event)
	return true

func reset_to_defaults() -> void:
	for action in _default_events:
		var ev = _default_events[action]
		if ev:
			rebind_action(action, ev)
EOF
