extends Control

@export var action_name: StringName

var _listening := false

func _ready() -> void:
	# In a real game, connect to InputRemapper.action_rebound to update display.
	_update_display()
	InputRemapper.action_rebound.connect(_on_rebound)

func _on_rebound(action: StringName, event: InputEvent) -> void:
	if action == action_name:
		_update_display()

func _update_display() -> void:
	var ev = InputRemapper.get_action_event(action_name)
	if ev:
		tooltip_text = ev.as_text()
